 76	function chime(event: "done" | "waiting") {
 77	  const key = event === "done" ? "ap_sound_done" : "ap_sound_waiting";
 78	  const legacy = localStorage.getItem("ap_sound"); // pre-split toggle
 79	  const enabled = localStorage.getItem(key) ?? (legacy === "0" ? "0" : "1");
