155	export function sleep(ms: number): Promise<void> {
156	  return new Promise((r) => setTimeout(r, ms));
157	}
  1	// Shared window-position helpers. Both the engine (tick loop) and the physics
  2	// module (throw/fall) need to read and write the pet window's logical position;
  3	// centralizing it keeps the DPI conversion in one place and avoids two copies
  4	// of the same `outerPosition / scaleFactor` dance drifting apart.
