  1	// Shared types and constants for the roam subsystem.
  2	
  3	import { getCurrentWindow } from "@tauri-apps/api/window";
  4	
  5	export type RoamMode = "stay" | "wander" | "cursor" | "climb";
  6	
  7	export type Point = { x: number; y: number };
  8	
  9	export type Rect = {
 10	  left: number;
 11	  top: number;
 12	  right: number;
 13	  bottom: number;
 14	};
 15	
 16	export type SystemWindow = {
 17	  title: string;
 18	  rect: Rect;
 19	};
 20	
 21	export type Environment = {
 22	  /// Work area of the current monitor (excludes taskbar), in logical pixels.
 23	  workArea: Rect;
 24	  /// Other application windows visible on screen, in logical pixels.
 25	  /// Empty on platforms where enumeration is unavailable.
 26	  windows: SystemWindow[];
 27	};
 28	
 29	export type Config = {
 30	  enabled: boolean;
 31	  mode: RoamMode;
 32	  speed: number;
 33	};
 34	
 35	export type ConfigSource = () => Config;
 36	
 37	export const ROAM_KEY = "ap_roam";
 38	export const ROAM_MODE_KEY = "ap_roam_mode";
 39	export const ROAM_SPEED_KEY = "ap_roam_speed";
 40	
 41	export const WIN_W = 260;
 42	export const WIN_H = 320;
 43	export const MARGIN = 40;
 44	
 45	export const IDLE_MS_MIN = 1200;
 46	export const IDLE_MS_MAX = 3500;
 47	
 48	export const PHYSICS_FRICTION = 0.9;
 49	export const PHYSICS_MIN_SPEED = 15;
 50	export const PHYSICS_GRAVITY = 1800;
 51	export const SAMPLE_WINDOW_MS = 120;
 52	
 53	export const TICK_MS = 30;
 54	/// Fixed dt (seconds) used by physics integration. Derived from TICK_MS so the
 55	/// two can never drift apart. All `vx * 0.03` style computations use this.
 56	export const DT_SEC = TICK_MS / 1000;
 57	
 58	/// Below this drag-release speed (px/s), no throw is applied , the pet just stays.
 59	export const THROW_MIN_SPEED = 15;
 60	
 61	/// Pet falls asleep after this many ms idle with no movement (Oneko-style).
 62	export const SLEEP_AFTER_MS = 30_000;
 63	/// Default spritesheet row for the sleep pose. Row 5 ("Failed") is unused by any
 64	/// mood in STATE_ROW, so it's free. Override with localStorage `ap_bind_sleep`.
 65	export const SLEEP_ROW_DEFAULT = 5;
 66	
 67	export const VALID_MODES: RoamMode[] = ["stay", "wander", "cursor", "climb"];
 68	
 69	/// Per-window override key. Each pet window (main, project, extra) can have
 70	/// its own roam mode / size, stored under `ap_win_<label>_<key>`. Falls back
 71	/// to the global key if the per-window override is absent.
 72	// Cache the label once at module load: getCurrentWindow() allocates a new
 73	// WebviewWindow each call, and loadConfig() runs every 30ms tick.
 74	const WIN_LABEL: string = (() => {
 75	  try {
 76	    return getCurrentWindow().label;
 77	  } catch {
 78	    return "";
 79	  }
 80	})();
 81	
 82	function winOverride(key: string): string | null {
 83	  if (!WIN_LABEL) return null;
 84	  return localStorage.getItem(`ap_win_${WIN_LABEL}_${key}`);
 85	}
 86	
 87	// Module-level cache: loadConfig() runs every 30ms tick; reading three keys
 88	// + parseInt ~100 times/sec is pure waste. Invalidated by `storage` events
 89	// (cross-window writes from Settings) and by invalidateRoamConfig() for
 90	// same-window writes.
 91	let cfgCache: Config | null = null;
 92	let cfgRaw = "";
 93	
 94	function snapshotRoamRaw(): string {
 95	  return `${localStorage.getItem(ROAM_KEY)}|${winOverride(ROAM_MODE_KEY) ?? ""}|${localStorage.getItem(ROAM_MODE_KEY)}|${localStorage.getItem(ROAM_SPEED_KEY)}`;
 96	}
 97	
 98	export function invalidateRoamConfig(): void {
 99	  cfgCache = null;
100	  cfgRaw = "";
101	}
102	
103	let configSource: ConfigSource | null = null;
104	
105	export function setRoamConfigSource(source: ConfigSource | null): void {
106	  configSource = source;
107	  invalidateRoamConfig();
108	}
109	
110	function normalizeConfig(raw: Config): Config {
111	  return {
112	    enabled: raw.enabled,
113	    mode: VALID_MODES.includes(raw.mode) ? raw.mode : "wander",
114	    speed: Math.max(1, Math.min(10, Math.round(raw.speed))),
115	  };
116	}
117	
118	export function loadConfig(): Config {
119	  if (configSource) return normalizeConfig(configSource());
120	  // Per-window roam mode override wins over the global setting for legacy
121	  // windows. Desktop instances inject their own config above instead.
122	  const raw = snapshotRoamRaw();
123	  if (cfgCache && raw === cfgRaw) return cfgCache;
124	  cfgRaw = raw;
125	  const stored = (winOverride(ROAM_MODE_KEY) || localStorage.getItem(ROAM_MODE_KEY)) as RoamMode | null;
126	  const mode: RoamMode = stored && VALID_MODES.includes(stored) ? stored : "wander";
127	  cfgCache = {
128	    enabled: localStorage.getItem(ROAM_KEY) !== "0",
129	    mode,
130	    speed: Math.max(1, Math.min(10, parseInt(localStorage.getItem(ROAM_SPEED_KEY) || "5", 10))),
131	  };
132	  return cfgCache;
133	}
134	
135	if (typeof window !== "undefined") {
136	  window.addEventListener("storage", (e) => {
137	    if (!e.key || e.key === ROAM_KEY || e.key === ROAM_MODE_KEY || e.key === ROAM_SPEED_KEY ||
138	        e.key.startsWith("ap_win_")) {
139	      invalidateRoamConfig();
140	    }
141	  });
142	}
143	
144	export function clampToBounds(pos: Point, bounds: Rect): Point {
145	  return {
146	    x: Math.max(bounds.left, Math.min(bounds.right - WIN_W, pos.x)),
147	    y: Math.max(bounds.top, Math.min(bounds.bottom - WIN_H, pos.y)),
148	  };
149	}
150	
151	export function pxPerSec(speed: number): number {
152	  return 40 + speed * 45;
153	}
154	
155	export function sleep(ms: number): Promise<void> {
156	  return new Promise((r) => setTimeout(r, ms));
157	}
  1	// Shared window-position helpers. Both the engine (tick loop) and the physics
  2	// module (throw/fall) need to read and write the pet window's logical position;
  3	// centralizing it keeps the DPI conversion in one place and avoids two copies
  4	// of the same `outerPosition / scaleFactor` dance drifting apart.
  5	
  6	import { getCurrentWindow } from "@tauri-apps/api/window";
  7	import { LogicalPosition } from "@tauri-apps/api/dpi";
  8	import type { Point } from "./types";
  9	
 10	const win = getCurrentWindow();
 11	
 12	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
 13	/// window or scaleFactor can't be read (e.g. window closing).
 14	export async function currentLogicalPos(): Promise<Point | null> {
 15	  try {
 16	    const sf = await win.scaleFactor();
 17	    const p = await win.outerPosition();
 18	    return { x: p.x / sf, y: p.y / sf };
 19	  } catch {
 20	    return null;
 21	  }
 22	}
 23	
 24	/// Move the window to a logical-pixel position. Caller is responsible for
 25	/// clamping to the work area first.
 26	export async function setLogical(pos: Point): Promise<void> {
 27	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
 28	}

