     1	// Movement strategies. Each mode is a pure function: given the current
     2	// position and environment, return the next position (and animate the pet).
     3	// The engine drives the tick loop; modes stay stateless where possible.
     4	
     5	import { cursorPosition } from "@tauri-apps/api/window";
     6	import type { Pet } from "../pet";
     7	import type { Environment, Point, Rect, RoamMode } from "./types";
     8	import {
     9	  DT_SEC,
    10	  IDLE_MS_MAX,
    11	  IDLE_MS_MIN,
    12	  MARGIN,
    13	  WIN_H,
    14	  WIN_W,
    15	  clampToBounds,
    16	  loadConfig,
    17	  pxPerSec,
    18	} from "./types";
    19	
    20	const ROW_RIGHT = 1;
    21	const ROW_LEFT = 2;
    22	
    23	export interface ModeContext {
    24	  env: Environment;
    25	  pos: Point;
    26	  pet: Pet | null;
    27	}
    28	
    29	/// Dispatches to the active mode and returns the next position (or the
    30	/// unchanged position if the mode didn't move). Each mode handles its own
    31	/// animation row; if no movement happens, the caller clears the row.
    32	export async function runMode(mode: RoamMode, ctx: ModeContext): Promise<Point> {
    33	  switch (mode) {
    34	    case "stay": return ctx.pos;
    35	    case "cursor": return followCursor(ctx);
    36	    case "climb": return climb(ctx);
    37	    case "wander":
    38	    default: return wander(ctx);
    39	  }
    40	}
    41	
    42	/// Chase the mouse cursor. Stops beside it so it doesn't cover the pointer.
    43	async function followCursor(ctx: ModeContext): Promise<Point> {
    44	  const { env, pos, pet } = ctx;
    45	  try {
    46	    const sf = (await import("@tauri-apps/api/window")).getCurrentWindow();
    47	    const factor = await sf.scaleFactor();
    48	    const cur = await cursorPosition();
    49	    const target = {
    50	      x: cur.x / factor - WIN_W / 2,
    51	      y: cur.y / factor - WIN_H + 20,
    52	    };
