 272	fn build_desktop_pet_window(
 273	    app: &tauri::AppHandle,
 274	    instance: &DesktopPetWindow,
 275	    index: usize,
 276	) -> Result<(), String> {
 277	    let label = pet_window_label(&instance.id);
 278	    if let Some(window) = app.get_webview_window(&label) {
 279	        if instance.visible && read_desktop_pets_visible() {
 280	            window.show().map_err(|error| error.to_string())?;
 281	        } else {
 282	            window.hide().map_err(|error| error.to_string())?;
 283	        }
 284	        return Ok(());
 285	    }
 286	
 287	    let url = format!("index.html?pet={}", instance.id);
 288	    let mut builder = WebviewWindowBuilder::new(app, &label, WebviewUrl::App(url.into()))
 289	        .title("DesktopPet")
 290	        .inner_size(260.0, 320.0)
 291	        .transparent(true)
 292	        .decorations(false)
 293	        .always_on_top(true)
 294	        .skip_taskbar(true)
 295	        .resizable(false)
 296	        .shadow(false)
 297	        .focused(false)
 298	        .visible(instance.visible && read_desktop_pets_visible());
 299	    builder = match saved_pet_position(app, &instance.id) {
 300	        Some((x, y)) => {
 301	            let (x, y) = logical_position_for_physical(app, x, y);
 302	            builder.position(x, y)
 303	        }
 304	        None => {
 305	            let (x, y) = default_pet_position(app, index);
 306	            builder.position(x, y)
 307	        }
 308	    };
 309	    builder.build().map_err(|error| error.to_string())?;
 310	    Ok(())
 311	}
 312	
 313	fn sync_desktop_pet_windows_impl(app: tauri::AppHandle, pets: Vec<DesktopPetWindow>) {
 314	    use std::collections::HashSet;
 315	    let wanted: HashSet<String> = pets.iter().map(|pet| pet_window_label(&pet.id)).collect();
 316	    for (label, window) in app.webview_windows() {
 317	        if is_pet_window(&label) && !wanted.contains(&label) {
 318	            let _ = window.close();
 319	        }
 320	    }
 321	    for (index, pet) in pets.iter().enumerate() {
 322	        if let Err(error) = build_desktop_pet_window(&app, pet, index) {
 323	            dlog(&format!("desktop pet window failed for {}: {error}", pet.id));
 324	        }
 325	    }
 326	}
 327	
 328	/// Reconciles every persistent desktop-pet instance with a single frontend
 329	/// source of truth. Window labels are opaque IDs, never sprite slugs or projects.
 330	#[tauri::command]
 331	async fn sync_desktop_pet_windows(
 332	    app: tauri::AppHandle,
 333	    pets: Vec<DesktopPetWindow>,
 334	) -> Result<(), String> {
 335	    if pets.len() > MAX_DESKTOP_PETS {
 336	        return Err(format!("desktop pet limit is {MAX_DESKTOP_PETS}"));
 337	    }
 338	    let mut ids = std::collections::HashSet::new();
 339	    for pet in &pets {
 340	        if !valid_pet_id(&pet.id) || !ids.insert(&pet.id) {
 341	            return Err("invalid or duplicate desktop pet id".into());
 342	        }
 343	    }
 344	    let generation = app
 345	        .try_state::<Mutex<DesktopPetSyncState>>()
 346	        .and_then(|state| state.lock().ok().map(|mut state| {
 347	            state.generation = state.generation.wrapping_add(1);
 348	            state.generation
 349	        }))
 350	        .ok_or("desktop pet sync state unavailable")?;
 351	    std::thread::spawn(move || {
 352	        let is_current = app
 353	            .try_state::<Mutex<DesktopPetSyncState>>()
 354	            .and_then(|state| state.lock().ok().map(|state| state.generation == generation))
 355	            .unwrap_or(false);
 356	        if is_current {
 357	            sync_desktop_pet_windows_impl(app, pets);
 358	        }
 359	    });
 360	    Ok(())
 361	}
