 363	/// The floating ball window label. A single instance lives on the desktop as a
 364	/// stable click target (left = bubble menu, right = Settings) so the user
 365	/// doesn't have to chase a roaming pet.
 552	/// Show or hide all desktop-pet windows without changing their instance data.
 553	#[tauri::command]
 554	fn set_desktop_pets_visible(app: tauri::AppHandle, visible: bool) {
 555	    write_desktop_pets_visible(visible);
 556	    for (label, window) in app.webview_windows() {
 557	        if is_pet_window(&label) {
 558	            let _ = if visible { window.show() } else { window.hide() };
 559	        }
 560	    }
 561	    if let Some(items) = app.try_state::<Mutex<TrayItems>>() {
 562	        if let Ok(items) = items.lock() {
 563	            let _ = items.show_pet.set_checked(visible);
 564	        }

